class _Rules(Rules):
    """ActionDropout (A axis, harder with DOSE): with probability DOSE, silently drop the agent's
    chosen action and replace it with a no-op action that leaves the world unchanged. The world is
    untouched, so a patient policy can retry the action on a later step and still solve the task.
    The dropout is deterministic per (task_id, step) via a hash so the masked step set is nested
    in DOSE."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _dropped(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def modify_action(self, action, env_state):
        if self._dropped(env_state):
            return Action("look")
        return action

