        key = f"{self.TASK_ID}:{step}:{action}"
        digest = hashlib.sha256(key.encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def modify_action(self, action, env_state):
        if self._dropped(env_state, action):
            return Action("")
        return action

