class _Rules(Rules):
    """ObservationNoise (O axis, harder with DOSE): with probability DOSE, replace the
    observation text with a hashed/obfuscated version (keeping structure but hiding content).
    Deterministic per (task_id, step), nested in DOSE. The world is untouched, so the task stays
    solvable; the agent must rely on memory of earlier unmasked observations."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _noised(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._noised(env_state):
            return obs
        text = obs.text
        lines = text.split("\n")
        out = []
        for ln in lines:
            if "Admissible commands:" in ln or ln.startswith("> "):
                out.append(ln)
            elif ln.strip():
                out.append("[noise]")
            else:
                out.append(ln)
        return Observation(text="\n".join(out), data=obs.data)

class _Rules(Rules):
    """ActionEchoSwap (A axis, harder with DOSE): with probability DOSE, the last command is
    silently replaced by a no-op echo of itself before being passed to the world. This forces
    the policy to re-issue commands that were dropped. At DOSE=1 every action is dropped, which
    would make success impossible, so the drop is capped so that at least the final required
    step can still succeed (cap at 0.5). World is untouched, task remains solvable."""

    DOSE = __DOSE__

    def modify_action(self, action, env_state):
        p = min(self.DOSE, 0.5)
        if p <= 0:
            return action
        step = int(getattr(env_state, "step_count", 0) or 0)
        if (step * 2654435761) % 100000 / 100000.0 < p:
            return Action("echo dropped-command")
        return action

