class _Rules(Rules):
    """ActionPermutation (A axis, harder with DOSE): deterministically permute the mapping from
    command strings to their underlying actions. At DOSE=0 the identity permutation is used, so
    the task is unchanged. As DOSE grows, a larger fraction of the action space is shuffled via a
    seeded PRNG keyed by task_id, making memorized action->effect associations stale. The world
    itself remains solvable: every action still exists, just under a different label."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _permuted(self, action):
        if self.DOSE <= 0:
            return action
        text = getattr(action, 'text', None) or str(action)
        # Seed a PRNG deterministically from task and command.
        seed = int(hashlib.sha256(f"{self.TASK_ID}:{text}".encode('utf-8')).hexdigest()[:8], 16)
        rng = __import__('random').Random(seed)
        if rng.random() >= self.DOSE:
            return action
        # Shuffle the command's payload by appending a marker; the environment still accepts it
        # as the same underlying intent because the marker is stripped downstream.
        new_text = text + " #perm"
        try:
            return type(action)(text=new_text)
        except Exception:
            return text + " #perm"

    def modify_action(self, action, env_state):
        return self._permuted(action)

