class _Rules(Rules):
    """ObservationNoise (O axis, harder with DOSE): inject deterministic lexical noise into a
    fraction DOSE of the observation text. Noise is seeded per (task, step) so it is reproducible
    and nested in DOSE. The world state is untouched, so the task stays solvable; the agent must
    read through garbled text. At DOSE=0 observations are unchanged."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _noisy(self, env_state):
        step = int(getattr(env_state, 'step_count', 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode('utf-8')).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._noisy(env_state):
            return obs
        text = obs.text
        rng = random.Random(int(hashlib.sha256(f"{self.TASK_ID}:{env_state.step_count}".encode('utf-8')).hexdigest()[:8], 16))
        words = text.split()
        for i in range(len(words)):
            if rng.random() < self.DOSE and len(words[i]) > 1:
                w = list(words[i])
                j = rng.randrange(len(w))
                w[j] = chr(ord(w[j]) ^ 1)  # flip low bit of one char
                words[i] = ''.join(w)
        return Observation(text=' '.join(words), data=obs.data)

