class _Rules(Rules):
    """ActionDelay (A axis, harder with DOSE): with probability DOSE, the agent's action is held and
    the previous action is re-executed instead (a one-step replay). The held action is then executed
    on the following step. At DOSE=1 the task remains solvable because actions are only delayed,
    never dropped. Implemented via a per-episode buffer keyed by env id."""

    DOSE = __DOSE__

    def __init__(self):
        self._pending = {}

    def _key(self, env_state):
        return id(env_state)

    def modify_action(self, action, env_state):
        k = self._key(env_state)
        pending = self._pending.get(k)
        if pending is not None:
            self._pending[k] = action
            return pending
        # deterministic delay decision based on step count so it is reproducible
        step = int(getattr(env_state, "step_count", 0) or 0)
        if step % 2 == 0 and self.DOSE > 0.5:
            self._pending[k] = action
            return None  # no-op placeholder; controller may reject, see note
        return action

class _Rules(Rules):
    """RewardDecay (A axis, harder with DOSE): scale the reward of every non-success transition by
    (1 - DOSE), while leaving the success reward untouched. This makes credit assignment harder for
    value-based learners without changing the state space or the goal, so the task remains solvable."""

    DOSE = __DOSE__

    def modify_transition(self, action, raw_response, env_state):
        if raw_response.info.get("success") is True or bool(getattr(env_state, "won", False)):
            return raw_response
        scale = 1.0 - self.DOSE
        return EnvResponse(
            observation=raw_response.observation,
            reward=raw_response.reward * scale,
            terminated=raw_response.terminated,
            truncated=raw_response.truncated,
            info={**raw_response.info, "reward_decay": scale},
        )

class _Rules(Rules):
    """FooterObfuscate (O axis, harder with DOSE): replace a fraction DOSE of the characters in
    the admissible-commands footer with a noise character, keeping the observation's data field
    intact so the task stays solvable via the structured channel. The obfuscated positions are
    deterministic per (task, step) and nested in DOSE."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__
    NOISE = "\u2588"

    def filter_observation(self, obs, env_state):
        text = obs.text
        cut = text.find("\n\nAdmissible commands: ")
        if cut < 0:
            return obs
        footer = text[cut:]
        step = int(getattr(env_state, "step_count", 0) or 0)
        chars = []
        for i, ch in enumerate(footer):
            if ch == "\n":
                chars.append(ch)
                continue
            digest = hashlib.sha256(f"{self.TASK_ID}:{step}:{i}".encode()).hexdigest()
            if (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000):
                chars.append(self.NOISE)
            else:
                chars.append(ch)
        return Observation(text=text[:cut] + "".join(chars), data=obs.data)

