class _Rules(Rules):
    """RewardNoise (A axis, harder with DOSE): add zero-mean deterministic noise to the reward on
    a fraction DOSE of steps. The sign of the original reward is never flipped, and success is
    never altered, so the task remains solvable. bucket = sha256(f"{task_id}:{step}:noise")[:8] %
    10000; noisy iff bucket < DOSE * 10000 (nested in DOSE)."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__
    AMPLITUDE = __AMPLITUDE__

    def _noisy(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}:noise".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def modify_reward(self, reward, env_state):
        if not self._noisy(env_state):
            return reward
        step = int(getattr(env_state, "step_count", 0) or 0)
        raw = int(hashlib.sha256(f"{self.TASK_ID}:{step}:jitter".encode("utf-8")).hexdigest()[:8], 16)
        noise = (raw / 0xFFFFFFFF - 0.5) * 2.0 * self.AMPLITUDE
        # never flip the sign of the reward
        if reward > 0:
            return max(0.0, reward + noise)
        if reward < 0:
            return min(0.0, reward + noise)
        return reward + noise

class _Rules(Rules):
    """RewardEchoPerturb (O axis, harder with DOSE): at a deterministic fraction DOSE of steps,
    an extra observation line is appended reporting a noisy 'score' that is uncorrelated with the
    true reward. The world and admissible commands are untouched, so solvability is preserved;
    higher DOSE injects more noise lines."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _masked(self, env_state):
        import hashlib
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._masked(env_state):
            return obs
        import hashlib
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:noise:{step}".encode("utf-8")).hexdigest()
        noise = (int(digest[:8], 16) % 2000) - 1000
        text = obs.text + f"\n[noise] score_delta={noise}"
        return Observation(text=text, data=obs.data)

