class _Rules(Rules):
    """CommandSwap (O axis, harder with DOSE): corrupt the admissible-commands list by
    swapping a deterministic fraction DOSE of commands with near-miss strings. The world is
    untouched and the true command text remains recoverable by position/context, so the task
    stays solvable."""

    DOSE = __DOSE__
    TASK_ID = __TASK_ID__

    def _perturbed(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}:swap".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def _swap(self, cmd):
        if cmd and cmd[0].islower():
            return cmd[0].upper() + cmd[1:]
        if cmd and cmd[0].isupper():
            return cmd[0].lower() + cmd[1:]
        return cmd

    def filter_observation(self, obs, env_state):
        if not self._perturbed(env_state):
            return obs
        data = dict(obs.data or {})
        cmds = data.get("admissible_commands")
        if isinstance(cmds, list) and cmds:
            data["admissible_commands"] = [self._swap(c) if isinstance(c, str) else c for c in cmds]
        return Observation(text=obs.text, data=data)

class _Rules(Rules):
    """RewardDelay (A axis, harder with DOSE): delay the terminal success reward by DOSE extra
    no-op steps. On a successful transition we withhold success and instead return a neutral
    observation for up to ceil(DOSE * K) consecutive steps, then release the original success.
    The world is untouched, so the task is solvable by construction."""

    DOSE = __DOSE__
    K = 3

    def modify_transition(self, action, raw_response, env_state):
        if raw_response.info.get("success") is True or bool(getattr(env_state, "won", False)):
            pending = int(getattr(env_state, "reward_delay_pending", 0) or 0)
            if pending == 0:
                pending = max(1, int(round(self.DOSE * self.K)))
            if pending > 1:
                env_state.reward_delay_pending = pending - 1
                return EnvResponse(
                    observation=raw_response.observation,
                    reward=0.0,
                    terminated=False,
                    truncated=False,
                    info={**raw_response.info, "success": False, "reward_delay": pending - 1},
                )
            env_state.reward_delay_pending = 0
        return raw_response
